const regions={
  asahidake:{label:'Asahidake',center:[142.854,43.663],zoom:11.0,bearing:12,pitch:54},
  rusutsu:{label:'Rusutsu',center:[140.88,42.74],zoom:11.0,bearing:-18,pitch:54},
  furano:{label:'Furano',center:[142.47,43.34],zoom:10.4,bearing:16,pitch:54},
  niseko:{label:'Niseko',center:[140.69,42.86],zoom:10.5,bearing:-20,pitch:54},
  kamui:{label:'Kamui Ski Links',center:[142.40,43.75],zoom:11.0,bearing:8,pitch:54},
  kiroro:{label:'Kiroro',center:[140.99,43.07],zoom:10.8,bearing:-12,pitch:54}
};
const state={points:[],drawing:false,apiKey:localStorage.getItem('powderline.maptilerKey')||'',saved:JSON.parse(localStorage.getItem('powderline.routes')||'[]')};
const $=s=>document.querySelector(s);
const map=new maplibregl.Map({container:'map',style:'https://demotiles.maplibre.org/style.json',center:regions.furano.center,zoom:regions.furano.zoom,bearing:regions.furano.bearing,pitch:regions.furano.pitch,antialias:true});
map.addControl(new maplibregl.NavigationControl({showCompass:true}), 'bottom-right');
function setTerrain(){if(map.getSource('terrain'))map.removeSource('terrain');try{map.addSource('terrain',{type:'raster-dem',url:state.apiKey?`https://api.maptiler.com/tiles/terrain-rgb-v2/tiles.json?key=${encodeURIComponent(state.apiKey)}`:'https://demotiles.maplibre.org/terrain-tiles/tiles.json',tileSize:256,maxzoom:14});map.setTerrain({source:'terrain',exaggeration:1.15});}catch(e){console.warn(e)}}
map.on('load',()=>{setTerrain();map.addSource('route',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'route-glow',type:'line',source:'route',paint:{'line-color':'#14211f','line-width':7,'line-opacity':.28,'line-blur':2}});map.addLayer({id:'route-line',type:'line',source:'route',paint:{'line-color':'#d8ff43','line-width':4,'line-opacity':1}});map.addSource('route-points',{type:'geojson',data:{type:'FeatureCollection',features:[]}});map.addLayer({id:'route-points',type:'circle',source:'route-points',paint:{'circle-radius':5,'circle-color':'#d8ff43','circle-stroke-color':'#14211f','circle-stroke-width':2}});render();});
function feature(){return {type:'Feature',geometry:{type:'LineString',coordinates:state.points.map(p=>[p.lng,p.lat])},properties:{}}}
function render(){if(!map.getSource('route'))return;map.getSource('route').setData(state.points.length>1?{type:'FeatureCollection',features:[feature()]}:{type:'FeatureCollection',features:[]});map.getSource('route-points').setData({type:'FeatureCollection',features:state.points.map((p,i)=>({type:'Feature',geometry:{type:'Point',coordinates:[p.lng,p.lat]},properties:{i}}))});$('#points').textContent=state.points.length;$('#distance').textContent=distanceKm(state.points).toFixed(1)+' km';$('#descent').textContent='—'}
function distanceKm(ps){let d=0;for(let i=1;i<ps.length;i++){const a=ps[i-1],b=ps[i],r=Math.PI/180, x=(b.lng-a.lng)*r*Math.cos((a.lat+b.lat)*r/2),y=(b.lat-a.lat)*r;d+=6371*Math.sqrt(x*x+y*y)}return d}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2500)}
function setRegion(){const r=regions[$('#region').value];map.flyTo({center:r.center,zoom:r.zoom,bearing:r.bearing,pitch:r.pitch,duration:1400});clearLine();toast('View moved to '+r.label)}
function clearLine(){state.points=[];state.drawing=false;$('#drawBtn').textContent='＋ Draw line';render()}
$('#region').addEventListener('change',setRegion);$('#clearBtn').addEventListener('click',clearLine);$('#drawBtn').addEventListener('click',()=>{state.drawing=!state.drawing;$('#drawBtn').textContent=state.drawing?'Finish line':'＋ Draw line';toast(state.drawing?'Click across the mountain to draw':'Line saved in canvas')});
map.on('click',e=>{if(!state.drawing)return;state.points.push({lng:e.lngLat.lng,lat:e.lngLat.lat});render()});map.on('dblclick',e=>{if(state.drawing){state.drawing=false;$('#drawBtn').textContent='＋ Draw line';toast('Line finished — drag vertices to refine it')}});
map.on('mousedown','route-points',e=>{if(!state.points.length)return;e.preventDefault();const i=e.features[0].properties.i;map.getCanvas().style.cursor='grabbing';map.on('mousemove',move);map.once('mouseup',up);function move(ev){state.points[i]={lng:ev.lngLat.lng,lat:ev.lngLat.lat};render()}function up(){map.getCanvas().style.cursor='';map.off('mousemove',move)}});
function gpxString(){const now=new Date().toISOString();return `<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="Powderline"><metadata><name>Powderline route</name><time>${now}</time></metadata><trk><name>Powderline line</name><trkseg>${state.points.map(p=>`<trkpt lat="${p.lat}" lon="${p.lng}"></trkpt>`).join('')}</trkseg></trk></gpx>`}
$('#exportBtn').addEventListener('click',()=>{if(state.points.length<2)return toast('Draw a line first');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([gpxString()],{type:'application/gpx+xml'}));a.download='powderline-route.gpx';a.click();toast('GPX exported')});
$('#gpxInput').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const xml=new DOMParser().parseFromString(await f.text(),'application/xml');state.points=[...xml.querySelectorAll('trkpt,rtept')].map(n=>({lat:+n.getAttribute('lat'),lng:+n.getAttribute('lon')}));render();if(state.points.length){const bounds=state.points.reduce((b,p)=>b.extend([p.lng,p.lat]),new maplibregl.LngLatBounds([state.points[0].lng,state.points[0].lat],[state.points[0].lng,state.points[0].lat]));map.fitBounds(bounds,{padding:90,duration:900,maxZoom:13})}toast(`${state.points.length} GPX points loaded`)});
function renderSaved(){const el=$('#savedList');$('#savedCount').textContent=state.saved.length;if(!state.saved.length){el.innerHTML='<p class="empty">No saved lines yet.</p>';return}el.innerHTML=state.saved.map((r,i)=>`<button class="saved-item" data-i="${i}"><span>${r.name}</span><small>${r.km.toFixed(1)} km</small></button>`).join('');el.querySelectorAll('.saved-item').forEach(b=>b.addEventListener('click',()=>{state.points=state.saved[+b.dataset.i].points;render();toast('Saved line loaded')}))}
$('#saveBtn').addEventListener('click',()=>{if(state.points.length<2)return toast('Draw a line first');const r=regions[$('#region').value];state.saved.unshift({name:r.label+' line '+new Date().toLocaleDateString('en-CA'),km:distanceKm(state.points),points:state.points});localStorage.setItem('powderline.routes',JSON.stringify(state.saved));renderSaved();toast('Route saved locally')});
$('#tiltBtn').addEventListener('click',()=>map.easeTo({pitch:map.getPitch()>20?15:58,duration:700}));$('#resetBtn').addEventListener('click',()=>setRegion());$('#apiKey').value=state.apiKey;$('#applyKey').addEventListener('click',()=>{state.apiKey=$('#apiKey').value.trim();localStorage.setItem('powderline.maptilerKey',state.apiKey);setTerrain();toast(state.apiKey?'MapTiler terrain applied':'Demo terrain applied')});renderSaved();
